solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int total;
        if (n <= 100) {
            total = n * 500;
        } else {
            total = 100 * 500 + (n - 100) * 800;
        }
        System.out.println(total);
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int total;
    if (n <= 100) {
        total = n * 500;
    } else {
        total = 100 * 500 + (n - 100) * 800;
    }
    cout << total << endl;
    return 0;
}
